CREATE TABLE connector_oauth(id text PRIMARY KEY,member_id uuid NOT NULL REFERENCES members(id),provider text NOT NULL,state_hash text NOT NULL,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE connector_tokens(tenant_id uuid NOT NULL REFERENCES tenants(id),provider text NOT NULL,encrypted text NOT NULL,expires_at timestamptz,PRIMARY KEY(tenant_id,provider));
CREATE TABLE external_snapshots(tenant_id uuid NOT NULL REFERENCES tenants(id),provider text NOT NULL,entity_type text NOT NULL,external_id text NOT NULL,data jsonb NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,provider,entity_type,external_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['connector_tokens','external_snapshots'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
